DELIMITER $$
CREATE TRIGGER `trg_sync_payroll_released_history_after_update` AFTER UPDATE ON `payroll_periods` FOR EACH ROW BEGIN
  IF NEW.`released` = 1 AND (OLD.`released` IS NULL OR OLD.`released` = 0) THEN
    INSERT INTO `payroll_released_history` (
      `id`,
      `payroll_period_id`,
      `person_id`,
      `person_name`,
      `department`,
      `period`,
      `days_present`,
      `daily_rate`,
      `late_penalty`,
      `late_count`,
      `gross`,
      `total_late_deduction`,
      `total_deductions`,
      `net`,
      `detailed_attendance`,
      `released`,
      `action`,
      `released_by`,
      `released_at`,
      `created_at`,
      `updated_at`
    )
    SELECT
      UUID(),
      NEW.`id`,
      NEW.`person_id`,
      p.`name`,
      p.`department`,
      NEW.`period`,
      NEW.`days_present`,
      NEW.`daily_rate`,
      NEW.`late_penalty`,
      NEW.`late_count`,
      NEW.`gross`,
      NEW.`total_late_deduction`,
      NEW.`total_deductions`,
      NEW.`net`,
      JSON_ARRAY(),
      1,
      'Released',
      NULL,
      NOW(),
      NOW(),
      NOW()
    FROM `persons` p
    WHERE p.`id` = NEW.`person_id`
    ON DUPLICATE KEY UPDATE
      `person_id` = VALUES(`person_id`),
      `person_name` = VALUES(`person_name`),
      `department` = VALUES(`department`),
      `period` = VALUES(`period`),
      `days_present` = VALUES(`days_present`),
      `daily_rate` = VALUES(`daily_rate`),
      `late_penalty` = VALUES(`late_penalty`),
      `late_count` = VALUES(`late_count`),
      `gross` = VALUES(`gross`),
      `total_late_deduction` = VALUES(`total_late_deduction`),
      `total_deductions` = VALUES(`total_deductions`),
      `net` = VALUES(`net`),
      `detailed_attendance` = VALUES(`detailed_attendance`),
      `released` = VALUES(`released`),
      `action` = VALUES(`action`),
      `released_at` = VALUES(`released_at`),
      `updated_at` = NOW();
  END IF;
END
$$
DELIMITER ;

